package org.dromara.property.resident.mysql;
import org.junit.jupiter.api.*; import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable; import java.sql.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
/** Resident JOIN、生命周期分组、逻辑删除与现有索引的真实 MySQL 8 验收。 */
@EnabledIfEnvironmentVariable(named="ZBM_TEST_DB_URL",matches=".+") class ResidentViewMySqlTest {
 Connection c; long pa=id(),pb=id(),b=id(),u=id(),ra=id(),rb=id(),customer=id(); List<Long> rels=new ArrayList<>();
 @BeforeEach void seed() throws Exception {c=DriverManager.getConnection(req("ZBM_TEST_DB_URL"),req("ZBM_TEST_DB_USER"),req("ZBM_TEST_DB_PASSWORD"));assertEquals("zbm_property_test",c.getCatalog());x("INSERT INTO pm_project(id,project_code,project_name,sort,status,del_flag) VALUES(?,?,'项目A',0,'0','0'),(?,?,'项目B',0,'0','0')",pa,"R"+pa,pb,"R"+pb);x("INSERT INTO pm_building(id,project_id,building_code,building_name,sort,status,del_flag) VALUES(?,?,?,'1号楼',0,'0','0')",b,pa,"B"+b);x("INSERT INTO pm_unit(id,project_id,building_id,unit_code,unit_name,sort,status,del_flag) VALUES(?,?,?,?,'1单元',0,'0','0')",u,pa,b,"U"+u);x("INSERT INTO pm_room(id,project_id,building_id,unit_id,room_code,room_no,sort,status,del_flag) VALUES(?,?,?,?,?,'101室',0,'0','0'),(?,?,?,?,?,'102室',0,'0','0')",ra,pa,b,u,"A"+ra,rb,pa,b,u,"A"+rb);x("INSERT INTO pm_customer(id,customer_no,customer_type,customer_name,mobile,status,lifecycle_status,version,del_flag) VALUES(?,?,'PERSON','张三','13800138000','0','ACTIVE',0,'0')",customer,"C"+customer);add("OWNER","ACTIVE",ra,"0");add("OWNER","ACTIVE",rb,"0");add("TENANT","ENDED",ra,"0");add("FAMILY","PENDING",ra,"0");add("OWNER","ENDED",ra,"1");}
 @AfterEach void clean() throws Exception {if(c==null)return;x("DELETE FROM pm_room_customer_rel WHERE customer_id=?",customer);x("DELETE FROM pm_customer WHERE id=?",customer);x("DELETE FROM pm_room WHERE id IN (?,?)",ra,rb);x("DELETE FROM pm_unit WHERE id=?",u);x("DELETE FROM pm_building WHERE id=?",b);x("DELETE FROM pm_project WHERE id IN (?,?)",pa,pb);c.close();}
 @Test void allEightAcceptanceFactsHoldAndPlanUsesRelationIndex() throws Exception {String base=" FROM pm_room_customer_rel r JOIN pm_customer c ON c.id=r.customer_id AND c.del_flag='0' JOIN pm_room rm ON rm.id=r.room_id AND rm.del_flag='0' JOIN pm_building b ON b.id=rm.building_id AND b.del_flag='0' JOIN pm_unit u ON u.id=rm.unit_id AND u.del_flag='0' WHERE r.project_id=? AND r.customer_id=? AND r.del_flag='0' AND r.status='0'";assertEquals(2,n("SELECT COUNT(*)"+base+" AND r.relation_type='OWNER' AND r.relation_status='ACTIVE'",pa,customer));assertEquals(0,n("SELECT COUNT(*)"+base+" AND r.relation_type='OWNER' AND r.relation_status='ENDED' AND r.del_flag='0' AND r.id IN (SELECT id FROM pm_room_customer_rel WHERE del_flag='1')",pa,customer));assertEquals(2,n("SELECT COUNT(*)"+base+" AND r.relation_status='ACTIVE'",pa,customer));assertEquals(1,n("SELECT COUNT(*)"+base+" AND r.relation_status='ENDED'",pa,customer));assertEquals(1,n("SELECT COUNT(*)"+base+" AND r.relation_status='PENDING'",pa,customer));assertEquals(0,n("SELECT COUNT(*)"+base.replace("r.project_id=?","r.project_id=?") ,pb,customer));try(var s=c.prepareStatement("SELECT b.building_name,u.unit_name,rm.room_no"+base+" AND r.relation_status='ACTIVE' LIMIT 1")){s.setLong(1,pa);s.setLong(2,customer);try(var rs=s.executeQuery()){assertTrue(rs.next());assertEquals("1号楼",rs.getString(1));assertEquals("1单元",rs.getString(2));assertTrue(Set.of("101室","102室").contains(rs.getString(3)));}}try(var s=c.prepareStatement("EXPLAIN SELECT r.id FROM pm_room_customer_rel r WHERE r.project_id=? AND r.relation_status='ACTIVE' AND r.status='0' AND r.del_flag='0'")){s.setLong(1,pa);try(var rs=s.executeQuery()){assertTrue(rs.next());assertNotEquals("ALL",rs.getString("type"));}}}
 void add(String type,String status,long room,String deleted)throws Exception{long id=id();rels.add(id);x("INSERT INTO pm_room_customer_rel(id,project_id,room_id,customer_id,relation_type,is_primary,start_date,relation_status,status,del_flag) VALUES(?,?,?,?,?,'0',CURRENT_DATE,?,'0',?)",id,pa,room,customer,type,status,deleted);}
 int n(String sql,Object...v)throws Exception{try(var s=c.prepareStatement(sql)){for(int i=0;i<v.length;i++)s.setObject(i+1,v[i]);try(var r=s.executeQuery()){assertTrue(r.next());return r.getInt(1);}}} void x(String sql,Object...v)throws Exception{try(var s=c.prepareStatement(sql)){for(int i=0;i<v.length;i++)s.setObject(i+1,v[i]);s.executeUpdate();}}
 static String req(String n){String v=System.getenv(n);if(v==null||v.isBlank())throw new IllegalStateException(n+" required");return v;} static long id(){return Math.abs(UUID.randomUUID().getMostSignificantBits()>>>1);}
}
